//! The import of a DataVolley file from the team list: "i", the file, then
//! a step at a time, each team imported or not on its own.

#[cfg(test)]
mod tests {
    use crate::localization::current_labels;
    use crate::tests::ui::{TeamFixture, Ui};
    use crokey::crossterm::event::KeyCode;

    /// Three sets won by the home team, generated by the tests of the
    /// core: home players 1 to 7 (`Name1 Surname1`...), the libero 7;
    /// visiting 11 to 17. Played on 2015-01-25, season 2014/2015.
    const THREE_SETS: &str = include_str!("fixtures/three_sets.dvw");

    const TEAMS: &[TeamFixture] = &[TeamFixture {
        name: "Volley Club",
        players: &["Anna", "Bea", "Carla", "Dora", "Elsa", "Fede", "Gina"],
        opponents: &[],
    }];

    fn file(home: &str, visiting: &str) -> String {
        THREE_SETS
            .replacen("H;Home;", &format!("H;{home};"), 1)
            .replacen("V;Visiting;", &format!("V;{visiting};"), 1)
    }

    /// The team list, then the file chosen among the files.
    async fn opened(teams: &[TeamFixture], text: &str) -> Ui {
        let mut ui = Ui::start(teams, &[]).await;
        ui.browse_file("match.dvw", text.as_bytes());
        ui.press(KeyCode::Char('i')).await;
        ui.press(KeyCode::Enter).await;
        ui
    }

    /// The new team filled in, as the form of a team: the second level
    /// (high national), the first gender (men), the country typed.
    async fn fill_new_team(ui: &mut Ui) {
        ui.type_keys(&[KeyCode::Right, KeyCode::Down, KeyCode::Down])
            .await;
        for c in "Austria".chars() {
            ui.press(KeyCode::Char(c)).await;
        }
    }

    fn shows(ui: &mut Ui, text: &str) -> bool {
        ui.screen().contains(text)
    }

    fn saved_team_names(ui: &Ui) -> Vec<String> {
        let mut names: Vec<String> = ui
            .saved_teams()
            .iter()
            .filter_map(|t| t["name"].as_str().map(str::to_string))
            .collect();
        names.sort();
        names
    }

    /// The file shown, the team asked: home, away or both.
    #[tokio::test]
    async fn the_file_and_the_teams_to_import() {
        let labels = current_labels();
        let mut ui = opened(TEAMS, &file("Wien", "Graz")).await;
        let screen = ui.screen();
        for text in [
            labels.import_dvw,
            "Wien - Graz",
            "2015-01-25",
            "25-0, 25-0, 25-0",
            labels.dvw_which_team,
            "Wien (home)",
            "Graz (away)",
            labels.dvw_both,
        ] {
            assert!(screen.contains(text), "{text}: {screen}");
        }
    }

    /// The home team, new: the substitutions of the time (six before
    /// 2026), its gender, then saved with its match; back to the teams.
    #[tokio::test]
    async fn a_new_team_imported() {
        let labels = current_labels();
        let mut ui = opened(TEAMS, &file("Wien", "Graz")).await;
        ui.press(KeyCode::Enter).await;
        assert!(shows(&mut ui, labels.dvw_substitutions), "{}", ui.screen());
        assert!(
            ui.rows_containing(&["6"])
                .iter()
                .any(|r| r.contains(labels.max_substitutions))
        );
        ui.press(KeyCode::Enter).await;
        let question = labels
            .dvw_new_team_of
            .replace("{team}", "Wien")
            .replace("{year}", "2014");
        assert!(shows(&mut ui, &question), "{}", ui.screen());
        fill_new_team(&mut ui).await;
        ui.press(KeyCode::Enter).await;
        let ready = labels
            .dvw_ready
            .replace("{team}", "Wien")
            .replace("{sets}", "3")
            .replace("{players}", "7");
        assert!(shows(&mut ui, &ready), "{}", ui.screen());
        ui.press(KeyCode::Enter).await;
        let done = labels.dvw_imported.replace("{team}", "Wien");
        assert!(shows(&mut ui, &done), "{}", ui.screen());
        assert_eq!(saved_team_names(&ui), vec!["Volley Club", "Wien"]);
        let wien = ui
            .saved_teams()
            .into_iter()
            .find(|t| t["name"] == "Wien")
            .expect("Wien saved");
        assert_eq!(wien["classification"], "HighNational", "{wien}");
        assert_eq!(wien["gender"], "Men", "{wien}");
        assert_eq!(wien["country"], "AT", "{wien}");
        let matches = ui.saved_matches();
        assert_eq!(matches.len(), 1, "{matches:?}");
        assert_eq!(matches[0]["opponent"], "Graz");
        assert_eq!(matches[0]["max_substitutions"], 6);
        ui.press(KeyCode::Enter).await;
        assert!(
            ui.rows_containing(&["Wien"]).len() == 1,
            "back to the teams: {}",
            ui.screen()
        );
    }

    /// The new team without its country: said as by the form of a team,
    /// the user still on it; nothing saved.
    #[tokio::test]
    async fn a_new_team_needs_its_country() {
        let labels = current_labels();
        let mut ui = opened(TEAMS, &file("Wien", "Graz")).await;
        ui.type_keys(&[KeyCode::Enter, KeyCode::Enter, KeyCode::Enter])
            .await;
        assert!(
            shows(&mut ui, labels.domain.country_is_required),
            "{}",
            ui.screen()
        );
        assert!(shows(&mut ui, labels.country), "{}", ui.screen());
        assert_eq!(ui.saved_matches().len(), 0);
        assert_eq!(saved_team_names(&ui), vec!["Volley Club"]);
    }

    /// Both teams: each imported on its own, the visiting one too.
    #[tokio::test]
    async fn both_teams_imported() {
        let labels = current_labels();
        let mut ui = opened(TEAMS, &file("Wien", "Graz")).await;
        ui.type_keys(&[KeyCode::Down, KeyCode::Down, KeyCode::Enter])
            .await;
        // substitutions, new Wien, saved, new Graz, saved
        ui.press(KeyCode::Enter).await;
        for _ in 0..2 {
            fill_new_team(&mut ui).await;
            ui.type_keys(&[KeyCode::Enter, KeyCode::Enter]).await;
        }
        let screen = ui.screen();
        for team in ["Wien", "Graz"] {
            let done = labels.dvw_imported.replace("{team}", team);
            assert!(screen.contains(&done), "{team}: {screen}");
        }
        assert_eq!(saved_team_names(&ui), vec!["Graz", "Volley Club", "Wien"]);
        assert_eq!(ui.saved_matches().len(), 2);
    }

    /// A team alike (the same name, the same season): proposed, why said;
    /// its players with the numbers of the file and other names stop the
    /// import, saying who; a new team instead imports it.
    #[tokio::test]
    async fn a_similar_team_proposed() {
        let labels = current_labels();
        // the season of the teams of the fixture
        let text = file("Volley Club", "Graz").replacen(
            "01/25/2015;;2014/2015",
            "10/25/2025;;2025/2026",
            1,
        );
        let mut ui = opened(TEAMS, &text).await;
        ui.type_keys(&[KeyCode::Enter, KeyCode::Enter]).await;
        let found = labels.dvw_similar_found.replace("{team}", "Volley Club");
        assert!(shows(&mut ui, &found), "{}", ui.screen());
        let rows = ui.rows_containing(&["Volley Club 2025"]);
        assert!(
            rows.iter().any(|r| r.contains(labels.dvw_same_name)),
            "{rows:?}"
        );
        assert!(shows(&mut ui, labels.dvw_new_team), "{}", ui.screen());
        ui.press(KeyCode::Enter).await;
        let conflict = "Name1 Surname1 in the file, Anna in the team";
        assert!(shows(&mut ui, conflict), "{}", ui.screen());
        assert_eq!(ui.saved_matches().len(), 0);
    }

    /// The same team, a new one chosen instead of the similar one.
    #[tokio::test]
    async fn a_new_team_instead_of_the_similar_one() {
        let labels = current_labels();
        let text = file("Volley Club", "Graz").replacen(
            "01/25/2015;;2014/2015",
            "10/25/2025;;2025/2026",
            1,
        );
        let mut ui = opened(TEAMS, &text).await;
        ui.type_keys(&[
            KeyCode::Enter,
            KeyCode::Enter,
            KeyCode::Down,
            KeyCode::Enter,
        ])
        .await;
        assert!(shows(&mut ui, labels.gender), "{}", ui.screen());
        fill_new_team(&mut ui).await;
        ui.type_keys(&[KeyCode::Enter, KeyCode::Enter]).await;
        let done = labels.dvw_imported.replace("{team}", "Volley Club");
        assert!(shows(&mut ui, &done), "{}", ui.screen());
        assert_eq!(saved_team_names(&ui), vec!["Volley Club", "Volley Club"]);
    }

    /// Day first or month first, both valid: the user chooses (day first
    /// listed first, 2 March; the second one, 3 February, chosen).
    #[tokio::test]
    async fn an_ambiguous_date_chosen() {
        let labels = current_labels();
        let text = file("Wien", "Graz").replacen("01/25/2015", "02/03/2015", 1);
        let mut ui = opened(TEAMS, &text).await;
        ui.press(KeyCode::Enter).await;
        assert!(shows(&mut ui, labels.dvw_which_date), "{}", ui.screen());
        assert!(shows(&mut ui, "2015-02-03"), "{}", ui.screen());
        assert!(shows(&mut ui, "2015-03-02"), "{}", ui.screen());
        ui.type_keys(&[KeyCode::Down, KeyCode::Enter]).await;
        // substitutions, new team, saved
        ui.press(KeyCode::Enter).await;
        fill_new_team(&mut ui).await;
        ui.type_keys(&[KeyCode::Enter, KeyCode::Enter]).await;
        let matches = ui.saved_matches();
        assert!(
            matches[0]["date"]
                .as_str()
                .is_some_and(|d| d.starts_with("2015-02-03")),
            "{matches:?}"
        );
    }

    /// A file whose sets don't add up: not imported, the reason said.
    #[tokio::test]
    async fn a_match_not_translated_is_not_imported() {
        let labels = current_labels();
        let text = file("Wien", "Graz").replacen("True;;;;25-0;;", "True;;;;25-3;;", 1);
        let mut ui = opened(TEAMS, &text).await;
        ui.type_keys(&[KeyCode::Enter, KeyCode::Enter]).await;
        fill_new_team(&mut ui).await;
        ui.press(KeyCode::Enter).await;
        let screen = ui.screen();
        assert!(
            screen.contains("set 1: 25-3 in the file, 25-0 from its rallies"),
            "{screen}"
        );
        assert!(
            screen.contains(
                &labels
                    .dvw_not_imported
                    .replace("{team}", "Wien")
                    .replace(", {reason}", "")
            ),
            "{screen}"
        );
        assert_eq!(ui.saved_matches().len(), 0);
        assert_eq!(saved_team_names(&ui), vec!["Volley Club"]);
    }

    /// Imported again into the same team: overwritten only when the user
    /// says so.
    #[tokio::test]
    async fn a_match_saved_already() {
        let labels = current_labels();
        let mut ui = opened(TEAMS, &file("Wien", "Graz")).await;
        // home, substitutions, new team, saved, back to the teams
        ui.type_keys(&[KeyCode::Enter, KeyCode::Enter]).await;
        fill_new_team(&mut ui).await;
        ui.type_keys(&[KeyCode::Enter, KeyCode::Enter, KeyCode::Enter])
            .await;
        ui.press(KeyCode::Char('i')).await;
        ui.press(KeyCode::Enter).await;
        // home, substitutions, Wien alike, ready
        for _ in 0..4 {
            ui.press(KeyCode::Enter).await;
        }
        let asked = labels.dvw_already_saved.replace("{team}", "Wien");
        assert!(shows(&mut ui, &asked), "{}", ui.screen());
        ui.type_keys(&[KeyCode::Down, KeyCode::Enter]).await;
        let skipped = labels.dvw_skipped.replace("{team}", "Wien");
        assert!(shows(&mut ui, &skipped), "{}", ui.screen());
        assert_eq!(ui.saved_matches().len(), 1);
        assert_eq!(saved_team_names(&ui), vec!["Volley Club", "Wien"]);
    }

    /// Esc goes back a step, and from the first one to the files.
    #[tokio::test]
    async fn esc_goes_back() {
        let labels = current_labels();
        let mut ui = opened(TEAMS, &file("Wien", "Graz")).await;
        ui.press(KeyCode::Enter).await;
        assert!(shows(&mut ui, labels.dvw_substitutions), "{}", ui.screen());
        ui.press(KeyCode::Esc).await;
        assert!(shows(&mut ui, labels.dvw_which_team), "{}", ui.screen());
        ui.press(KeyCode::Esc).await;
        assert!(shows(&mut ui, "match.dvw"), "{}", ui.screen());
        assert!(!shows(&mut ui, labels.dvw_which_team), "{}", ui.screen());
    }

    /// Not a DataVolley file: said where the file was chosen.
    #[tokio::test]
    async fn a_file_not_readable() {
        let mut ui = opened(TEAMS, "nothing here").await;
        let screen = ui.screen();
        assert!(screen.contains("can't be read as DataVolley"), "{screen}");
    }
}
